        "path": ".github/workflows/release.yml",
        "scope": "release",
        "action": "same"
      },
      {
        "path": "scripts/checkout-dependency.sh",
        "scope": "release",
        "action": "update",
        "diff": "--- scripts/checkout-dependency.sh\n+++ scripts/checkout-dependency.sh\n@@ -20,6 +20,15 @@\n # commit is pinned by its superproject, but its URL comes from that\n # repository's .gitmodules, which this pin does not name, so initialising\n # one fetches from a repository the product never declared.\n+#\n+# A dependency a runner may not fetch -- a private repository, on a machine\n+# that holds no credential for it -- can travel instead: when\n+# MAELYS_DEPENDENCY_BUNDLES names a directory holding NAME.bundle, that git\n+# bundle is cloned in place of the repository. The commit is checked the same\n+# way, by its own hash, so a bundle brings the pinned commit or nothing. A\n+# bundle carries no submodule, and a pin that declares them is refused rather\n+# than built without them. carry-dependencies.yml of maelys-release makes\n+# those bundles, on a machine that may read.\n set -eu\n name=${1:?NAME}\n case $name in *[!a-z0-9-]*|'') echo \"checkout-dependency: NAME must be [a-z0-9-]: $name\" >&2; exit 64 ;; esac\n@@ -41,7 +50,24 @@\n     echo \"checkout-dependency: refusing to replace existing path: $destination\" >&2\n     exit 1\n fi\n-git clone --quiet --filter=blob:none --no-checkout \"$repository\" \"$destination\"\n+bundle=\n+if [ -n \"${MAELYS_DEPENDENCY_BUNDLES:-}\" ] && [ -f \"$MAELYS_DEPENDENCY_BUNDLES/$name.bundle\" ]; then\n+    bundle=$MAELYS_DEPENDENCY_BUNDLES/$name.bundle\n+fi\n+if [ -n \"$bundle\" ]; then\n+    if sed -n '3,$p' \"$pin_file\" | grep -q '^submodules'; then\n+        echo \"checkout-dependency: $pin_file declares submodules, which a bundle does not carry\" >&2\n+        exit 65\n+    fi\n+    git clone --quiet --no-checkout \"$bundle\" \"$destination\"\n+    # The remote a clone of the repository would have: whatever runs after\n+    # this sees one shape of checkout, not two.\n+    git -C \"$destination\" remote set-url origin \"$repository\"\n+    source=\"bundle $bundle\"\n+else\n+    git clone --quiet --filter=blob:none --no-checkout \"$repository\" \"$destination\"\n+    source=$repository\n+fi\n git -C \"$destination\" checkout --quiet --detach \"$pin\"\n test \"$(git -C \"$destination\" rev-parse HEAD)\" = \"$pin\"\n submodules=$(sed -n 's|^submodules *\\(recursive\\)*$|\\1|p' \"$pin_file\" | head -n 1)\n@@ -57,4 +83,4 @@\n     git -C \"$destination\" submodule update --quiet \"$@\" --depth 1 ||\n         git -C \"$destination\" submodule update --quiet \"$@\"\n fi\n-echo \"$name $tag ($pin) from $repository in $destination\"\n+echo \"$name $tag ($pin) from $source in $destination\"\n",
        "touches": "mechanism"
      },
      {
        "path": "scripts/checkout-dependencies.sh",
        "scope": "release",
        "action": "update",
        "diff": "--- scripts/checkout-dependencies.sh\n+++ scripts/checkout-dependencies.sh\n@@ -27,6 +27,16 @@\n # Every pin, never a list of names: the jobs of maelys-egress named three\n # dependencies in five places each, and a fourth pin would have been the one\n # forgotten in one of them.\n+#\n+# Every pin but one kind: a pin whose file says 'on-request' is skipped here\n+# and cloned only when a job asks for it by name, through\n+# scripts/checkout-dependency.sh NAME. maelys-http pins Mbed TLS twice, and\n+# its second pin serves one job; every other job cloned it, submodules and\n+# all, without reading a file of it. The exception is declared in the pin,\n+# which is still the one place a dependency is named.\n+#\n+# And each clone says how long it took, on stderr: that cost was invisible,\n+# and a product had to compare two runs to see forty seconds a job.\n set -eu\n destination=${1:?usage: scripts/checkout-dependencies.sh DESTINATION}\n root=$(CDPATH='' cd -- \"$(dirname \"$0\")/..\" && pwd)\n@@ -40,7 +50,13 @@\n     name=${name%.pin}\n     # Reported on stderr with the clones themselves: stdout carries the one\n     # assignment, and a second line there would land in $GITHUB_ENV.\n+    if sed -n '3,$p' \"$pin_file\" | grep -q '^on-request$'; then\n+        echo \"checkout-dependencies: $name is cloned on request only (dependencies/$name.pin): skipped\" >&2\n+        continue\n+    fi\n+    started=$(date +%s)\n     sh \"$root/scripts/checkout-dependency.sh\" \"$name\" \"$destination/$name\" >&2\n+    echo \"checkout-dependencies: $name cloned in $(($(date +%s) - started))s\" >&2\n done\n # The socle is the last dependency that was still read beside the product.\n # It is not a dependencies/*.pin -- its commit is the one on the `uses:` line\n",
        "touches": "mechanism"
      },
