        "path": "AGENTS.md",
        "scope": "conventions",
        "action": "same"
      },
      {
        "path": "CLAUDE.md",
        "scope": "conventions",
        "action": "same"
      },
      {
        "path": ".claude/skills/maelys-release/SKILL.md",
        "scope": "release",
        "action": "same"
      },
      {
        "path": ".github/workflows/ci.yml",
        "scope": "conventions",
        "action": "same"
      }
    ],
